 "content": "from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = Counter(v for row in grid for v in row if v != 0)
    if not counts:
        return out
    frame = counts.most_common(1)[0][0]

    # Identify connected patches of each non-background, non-frame color.
    comps_by_color = {}
    seen = set()
    areas = Counter()
    comps = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or color == frame or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx)); q.append((ny,nx))
            comps.setdefault(color, []).append(cells)
            areas[color] += len(cells)

    # The most common remaining color is the repeated, unmarked tile fill.
    if not areas:
        return out
    background = areas.most_common(1)[0][0]
    for color, components in comps.items():
        if color == background:
            continue
        points = []
        for cells in components:
            # The center of a uniform patch is its anchor.
            points.append((round(sum(y for y, x in cells) / len(cells)),
                           round(sum(x for y, x in cells) / len(cells))))
        # Connect aligned matching anchors, coloring only empty gaps between tiles.
        for i, (r1, c1) in enumerate(points):
            for r2, c2 in points[i+1:]:
                if r1 == r2:
                    lo, hi = sorted((c1, c2))
                    for c in range(lo + 1, hi):
                        if out[r1][c] == 0:
                            out[r1][c] = color
                elif c1 == c2:
                    lo, hi = sorted((r1, r2))
                    for r in range(lo + 1, hi):
                        if out[r][c1] == 0:
                            out[r][c1] = color
    return out
